import { defineConfig } from "vite";
import vue from "@vitejs/plugin-vue";
import process from "node:process";
import { rmSync } from "node:fs";
import { resolve } from "node:path";
const backend = process.env.JUXIAOBAO_API_ORIGIN ?? "http://127.0.0.1:8080";
const webRoot = resolve(import.meta.dirname, "../web");
export default defineConfig({
  plugins: [
    {
      name: "clean-generated-web-assets",
      apply: "build",
      buildStart() {
        // Menu images are restored from the database and must survive a failed
        // backend build. Only remove files generated by Vite itself.
        for (const entry of ["assets", "admin", "index.html"])
          rmSync(resolve(webRoot, entry), { recursive: true, force: true });
      },
    },
    vue(),
  ],
  build: {
    outDir: webRoot,
    emptyOutDir: false,
    rollupOptions: { input: { main: "index.html", admin: "admin/index.html" } },
  },
  server: {
    proxy: {
      "/api": backend,
      "/menu-images": backend,
      "/uploads": backend,
      "/ws": { target: backend.replace("http", "ws"), ws: true },
    },
  },
});
